(function() {
    'use strict';

    class NEXUSAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'NEXUS: Marketplace Platform Economics';
            this.version = '1.1.0';
            this.BRIEFINGS = {
                1: 'briefingP1', 2: 'briefingP2', 3: 'briefingP3',
                4: 'briefingP4', 5: 'briefingP5', 6: 'briefingP6',
                7: 'briefingP7', 8: 'briefingP8', 9: 'briefingP9',
                10: 'briefingP10', 11: 'briefingP11', 12: 'briefingP12'
            };
            this.PHASE_EVENTS = {
                1: 'eventP1', 2: 'eventP2', 3: 'eventP3', 4: 'eventP4'
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2500000,
                    monthlyBurn: 138000,
                    registeredProviders: 847,
                    registeredClients: 312,
                    activeProviders: 0,
                    activeClients: 0,
                    gmv: 0,
                    netRevenue: 0,
                    platformLiquidity: 15,
                    providerNps: 0,
                    clientRetention: 0,
                    cacLtvRatio: 0,
                    multiHomingRate: 38,
                    trustIndex: 50,
                    qualityScore: 50,
                    avgTicketSize: 92,
                    transactionsPerClient: 1.5,
                    providerChurnRate: 35,
                    clientChurnRate: 60,
                    cumulativeMarketingSpend: 0,
                    cumulativeProviderAcquisitions: 0,
                    cumulativeClientAcquisitions: 0,
                    liquidityHistory: [],
                    gmvHistory: [],
                    revenueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    marketingBudget: 50000,
                    supplyVsDemandSplit: 60,
                    takeRate: 15,
                    qualityInvestment: 20000,
                    expansionInvestment: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var mbInput = document.getElementById('marketingBudget');
            if (mbInput) decisions.marketingBudget = parseInt(mbInput.value);

            var sdInput = document.getElementById('supplyVsDemand');
            if (sdInput) decisions.supplyVsDemandSplit = parseInt(sdInput.value);

            var trInput = document.getElementById('takeRate');
            if (trInput) decisions.takeRate = parseInt(trInput.value);

            var qiInput = document.getElementById('qualityInvestment');
            if (qiInput) decisions.qualityInvestment = parseInt(qiInput.value);

            var eiInput = document.getElementById('expansionInvestment');
            if (eiInput) decisions.expansionInvestment = parseInt(eiInput.value);

            var totalSpend = decisions.marketingBudget + decisions.qualityInvestment + decisions.expansionInvestment + state_ref().domainState.monthlyBurn;
            if (totalSpend > state_ref().domainState.cash) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceeded'), 'warning'
                );
            }

            if (decisions.takeRate < 5 || decisions.takeRate > 25) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('takerate_warning'), 'warning'
                );
                return false;
            }
            return true;

            function state_ref() { return window.mySimulation.state; }
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var phase = Math.ceil(period / 3);

            var supplyCost = d.marketingBudget * (d.supplyVsDemandSplit / 100);
            var demandCost = d.marketingBudget * ((100 - d.supplyVsDemandSplit) / 100);

            var qualityBoost = (d.qualityInvestment / 10000) * 1.8;
            ds.trustIndex = Math.min(100, ds.trustIndex + qualityBoost);
            ds.qualityScore = Math.min(100, ds.qualityScore + qualityBoost * 0.8);

            var networkMultiplier = 1 + Math.min(1.5, (ds.activeProviders * ds.activeClients) / 500000);
            var supplyGrowthBase = 15 + (supplyCost / 10000) * 3;
            var demandGrowthBase = 10 + (demandCost / 10000) * 4;

            supplyGrowthBase *= networkMultiplier;
            demandGrowthBase *= networkMultiplier;

            if (phase >= 2) {
                demandGrowthBase *= (1 + ds.platformLiquidity / 200);
            }

            var trustFactor = ds.trustIndex / 100;
            var supplyChurn = ds.activeProviders * (ds.providerChurnRate / 100) * (1 - trustFactor * 0.6) / 12;
            var clientChurn = ds.activeClients * (ds.clientChurnRate / 100) * (1 - (ds.platformLiquidity / 100) * 0.5) / 12;

            if (d.takeRate > 20) {
                var disintermediationPenalty = (d.takeRate - 20) * 0.04;
                supplyChurn *= (1 + disintermediationPenalty);
            }

            var expansionProviderBonus = 0;
            var expansionClientBonus = 0;
            if (d.expansionInvestment > 0) {
                if (ds.platformLiquidity < 60) {
                    var dilutionPenalty = 0.7;
                    expansionProviderBonus = (d.expansionInvestment / 15000) * dilutionPenalty;
                    expansionClientBonus = (d.expansionInvestment / 20000) * dilutionPenalty;
                    ds.platformLiquidity = Math.max(5, ds.platformLiquidity - 3);
                } else {
                    expansionProviderBonus = d.expansionInvestment / 12000;
                    expansionClientBonus = d.expansionInvestment / 15000;
                }
            }

            var newProviders = Math.round(supplyGrowthBase + expansionProviderBonus);
            var newClients = Math.round(demandGrowthBase + expansionClientBonus);

            ds.activeProviders = Math.max(10, Math.round(ds.activeProviders + newProviders - supplyChurn));
            ds.activeClients = Math.max(5, Math.round(ds.activeClients + newClients - clientChurn));

            ds.registeredProviders += newProviders;
            ds.registeredClients += newClients;

            ds.cumulativeMarketingSpend += d.marketingBudget;
            ds.cumulativeProviderAcquisitions += newProviders;
            ds.cumulativeClientAcquisitions += newClients;

            var providerClientRatio = ds.activeProviders > 0 ? ds.activeClients / ds.activeProviders : 0;
            var idealRatio = 5;
            var ratioBalance = 1 - Math.abs(providerClientRatio - idealRatio) / idealRatio;
            ratioBalance = Math.max(0, Math.min(1, ratioBalance));

            ds.platformLiquidity = Math.min(100, Math.max(5,
                15 + (ds.activeProviders / 50) * 2 + ratioBalance * 40 + (ds.trustIndex - 50) * 0.3
            ));

            if (phase >= 3) {
                ds.transactionsPerClient = Math.min(5, 1.5 + (ds.platformLiquidity / 100) * 2 + (ds.clientRetention / 100) * 1.5);
            } else if (phase >= 2) {
                ds.transactionsPerClient = Math.min(3.5, 1.5 + (ds.platformLiquidity / 100) * 1.2);
            }

            ds.avgTicketSize = 92 * (1 + (phase - 1) * 0.08);

            ds.gmv = Math.round(ds.activeClients * ds.transactionsPerClient * ds.avgTicketSize);
            ds.netRevenue = Math.round(ds.gmv * (d.takeRate / 100));

            var paymentProcessing = ds.gmv * 0.028;
            var supportCost = ds.activeClients * 2.4;
            var fraudCost = ds.gmv * 0.009;
            var variableCosts = paymentProcessing + supportCost + fraudCost;

            var grossProfit = ds.netRevenue - variableCosts;
            var totalPeriodCost = ds.monthlyBurn + d.marketingBudget + d.qualityInvestment + d.expansionInvestment;
            var periodCashFlow = grossProfit - totalPeriodCost;

            ds.cash = Math.max(0, Math.round(ds.cash + periodCashFlow));

            ds.providerNps = Math.round(Math.min(100, Math.max(-100,
                (ds.trustIndex - 50) * 0.6
                + (providerClientRatio > 3 ? 15 : providerClientRatio > 1 ? 5 : -10)
                - (d.takeRate - 15) * 2.5
                + (ds.platformLiquidity - 50) * 0.3
            )));

            ds.clientRetention = Math.round(Math.min(100, Math.max(0,
                15 + ds.platformLiquidity * 0.45 + ds.qualityScore * 0.25 + (ds.trustIndex - 50) * 0.15
            )));

            var providerCAC = ds.cumulativeProviderAcquisitions > 0 ? (ds.cumulativeMarketingSpend * 0.5) / ds.cumulativeProviderAcquisitions : 0;
            var clientCAC = ds.cumulativeClientAcquisitions > 0 ? (ds.cumulativeMarketingSpend * 0.5) / ds.cumulativeClientAcquisitions : 0;
            var blendedCAC = (providerCAC + clientCAC) / 2;

            var avgRevPerProvider = ds.activeProviders > 0 ? (ds.netRevenue * 12) / ds.activeProviders : 0;
            var avgRevPerClient = ds.activeClients > 0 ? (ds.netRevenue * 12) / ds.activeClients : 0;
            var blendedLTV = (avgRevPerProvider * 0.4 + avgRevPerClient * 0.6) * (ds.clientRetention / 100);

            ds.cacLtvRatio = blendedCAC > 0 ? Math.round((blendedLTV / blendedCAC) * 10) / 10 : 0;

            ds.multiHomingRate = Math.round(Math.max(5, Math.min(80,
                38 - ds.providerNps * 0.2 - (ds.trustIndex - 50) * 0.15 + (d.takeRate - 15) * 0.8
            )));

            if (phase >= 4) {
                ds.multiHomingRate = Math.min(80, ds.multiHomingRate + 8);
            }

            ds.providerChurnRate = Math.max(5, 35 - ds.trustIndex * 0.2 - ds.providerNps * 0.1 + (d.takeRate - 15) * 0.5);
            ds.clientChurnRate = Math.max(8, 60 - ds.platformLiquidity * 0.3 - ds.clientRetention * 0.2);

            ds.liquidityHistory.push(Math.round(ds.platformLiquidity));
            ds.gmvHistory.push(ds.gmv);
            ds.revenueHistory.push(ds.netRevenue);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: period,
                phase: phase,
                marketingBudget: d.marketingBudget,
                supplyVsDemandSplit: d.supplyVsDemandSplit,
                takeRate: d.takeRate,
                qualityInvestment: d.qualityInvestment,
                expansionInvestment: d.expansionInvestment,
                newProviders: newProviders,
                newClients: newClients,
                activeProviders: ds.activeProviders,
                activeClients: ds.activeClients,
                gmv: ds.gmv,
                netRevenue: ds.netRevenue,
                grossProfit: Math.round(grossProfit),
                cash: ds.cash,
                platformLiquidity: Math.round(ds.platformLiquidity),
                providerNps: ds.providerNps,
                clientRetention: ds.clientRetention,
                cacLtvRatio: ds.cacLtvRatio,
                multiHomingRate: ds.multiHomingRate,
                trustIndex: Math.round(ds.trustIndex)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashMetric', 'domainState.cash', (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('liquidityMetric', 'domainState.platformLiquidity', (v) => Math.round(v) + '%');
            uiManager.bind('gmvMetric', 'domainState.gmv', (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('revenueMetric', 'domainState.netRevenue', (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('npsMetric', 'domainState.providerNps', (v) => (v > 0 ? '+' : '') + Math.round(v));
            uiManager.bind('retentionMetric', 'domainState.clientRetention', (v) => Math.round(v) + '%');
            uiManager.bind('cacLtvMetric', 'domainState.cacLtvRatio', (v) => v > 0 ? v.toFixed(1) + ':1' : '—');
            uiManager.bind('multiHomingMetric', 'domainState.multiHomingRate', (v) => Math.round(v) + '%');
            uiManager.bind('trustMetric', 'domainState.trustIndex', (v) => Math.round(v));
            uiManager.bind('providersMetric', 'domainState.activeProviders', (v) => Math.round(v).toLocaleString());
            uiManager.bind('clientsMetric', 'domainState.activeClients', (v) => Math.round(v).toLocaleString());
