        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastState = history[history.length - 1];
            var ds = lastState.domainState || {};

            var liquidity = ds.platformLiquidity || 0;
            var retention = ds.clientRetention || 0;
            var cacLtv = ds.cacLtvRatio || 0;
            var netRev = ds.netRevenue || 0;
            var nps = ds.providerNps || 0;
            var trust = ds.trustIndex || 0;

            var liquidityScore = Math.min(100, liquidity) * 0.30;
            var retentionScore = Math.min(100, retention) * 0.20;
            var cacLtvScore = Math.min(100, Math.min(cacLtv, 5) * 20) * 0.20;
            var revenueScore = Math.min(100, Math.min(netRev / 1000, 100)) * 0.15;
            var npsScore = Math.min(100, Math.max(0, (nps + 100) / 2)) * 0.10;
            var trustScore = Math.min(100, trust) * 0.05;

            var mhs = Math.round(liquidityScore + retentionScore + cacLtvScore + revenueScore + npsScore + trustScore);

            var performance = 'Platform Casualty';
            var insights = [];
            if (mhs >= 75) {
                performance = 'Platform Visionary';
                insights.push(window.mySimulation.t('recommendationSuccess'));
            } else if (mhs >= 55) {
                performance = 'Competent Platform Builder';
                insights.push(window.mySimulation.t('recommendationDefault'));
            } else if (mhs >= 35) {
                performance = 'Pipeline Thinker';
                insights.push(window.mySimulation.t('recommendationLiquidity'));
            } else {
                insights.push(window.mySimulation.t('recommendationRetention'));
            }

            if (liquidity < 50) insights.push(window.mySimulation.t('recommendationLiquidity'));
            if (retention < 40) insights.push(window.mySimulation.t('recommendationRetention'));

            return {
                mhs: mhs,
                performance: performance,
                liquidity: Math.round(liquidity),
                clientRetention: Math.round(retention),
                cacLtvRatio: cacLtv,
                netRevenue: netRev,
                providerNps: Math.round(nps),
                trustIndex: Math.round(trust),
                cash: ds.cash || 0,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var phase = Math.ceil(state.currentPeriod / 3);
            if (results.platformLiquidity < 30 && phase <= 2) {
                return window.mySimulation.t('recommendationLiquidity');
            }
            if (results.clientRetention < 25) {
                return window.mySimulation.t('recommendationRetention');
            }
            if (state.domainState.cash < 300000) {
                return window.mySimulation.t('hint_cash_low');
            }
            if (results.multiHomingRate > 50) {
                return window.mySimulation.t('hint_multihoming');
            }
            var phaseKey = this.PHASE_EVENTS[phase];
            if (phaseKey) {
                return window.mySimulation.t(phaseKey);
            }
            return null;
        }

