        _wireSliders() {
            var self = this;
            var rows = [
                ['marketingBudget', 'marketingValue', function(v){ return '$' + Number(v).toLocaleString(); }],
                ['supplyVsDemand', 'supplyDemandValue', function(v){ return v + '% ' + window.mySimulation.t('supply'); }],
                ['takeRate', 'takeRateValue', function(v){ return v + '%'; }],
                ['qualityInvestment', 'qualityValue', function(v){ return '$' + Number(v).toLocaleString(); }],
                ['expansionInvestment', 'expansionValue', function(v){ return '$' + Number(v).toLocaleString(); }]
            ];
            rows.forEach(function(row){
                var input = document.getElementById(row[0]);
                var span = document.getElementById(row[1]);
                if (!input || !span) return;
                var fmt = row[2];
                var update = function(){ span.textContent = fmt(input.value); };
                input.addEventListener('input', update);
                input.addEventListener('change', update);
                update();
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1), 12);
            var briefKey = this.BRIEFINGS[idx] || 'briefingDefault';
            var briefEl = document.getElementById('briefingBox');
            if (briefEl) {
                briefEl.innerHTML = '<p>' + window.mySimulation.t(briefKey) + '</p>';
            }
            var phase = Math.ceil(idx / 3);
            var phaseKey = 'phase' + phase;
            var phaseEl = document.getElementById('phaseDisplay');
            if (phaseEl) {
                phaseEl.textContent = window.mySimulation.t(phaseKey);
            }
            var periodEl = document.getElementById('periodDisplay');
            if (periodEl) {
                periodEl.textContent = window.mySimulation.t('period_label') + ' ' + idx + '/12';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new NEXUSAdapter(), {
            simulationType: 'nexus_marketplace_economics',
            maxPeriods: 12,
            autoSaveInterval: 30000
        });
    });

